"""Tetris — falling blocks with rotation, wall-kicks and line clears."""

import random

from .base import Game, fg, RESET


class GameTetris(Game):
    name = "Tetris"
    order = 3
    realtime = True
    step_ms = 500
    controls = "←→ move · ↑ rotate · ↓ soft · Space hard/restart"
    W, H = 10, 20
    PIECES = {
        "I": (39, [[(0, 1), (1, 1), (2, 1), (3, 1)], [(2, 0), (2, 1), (2, 2), (2, 3)]]),
        "O": (227, [[(1, 0), (2, 0), (1, 1), (2, 1)]]),
        "T": (129, [[(1, 0), (0, 1), (1, 1), (2, 1)], [(1, 0), (1, 1), (2, 1), (1, 2)],
                    [(0, 1), (1, 1), (2, 1), (1, 2)], [(1, 0), (0, 1), (1, 1), (1, 2)]]),
        "S": (46, [[(1, 0), (2, 0), (0, 1), (1, 1)], [(1, 0), (1, 1), (2, 1), (2, 2)]]),
        "Z": (196, [[(0, 0), (1, 0), (1, 1), (2, 1)], [(2, 0), (1, 1), (2, 1), (1, 2)]]),
        "J": (33, [[(0, 0), (0, 1), (1, 1), (2, 1)], [(1, 0), (2, 0), (1, 1), (1, 2)],
                   [(0, 1), (1, 1), (2, 1), (2, 2)], [(1, 0), (1, 1), (0, 2), (1, 2)]]),
        "L": (208, [[(2, 0), (0, 1), (1, 1), (2, 1)], [(1, 0), (1, 1), (1, 2), (2, 2)],
                    [(0, 1), (1, 1), (2, 1), (0, 2)], [(0, 0), (1, 0), (1, 1), (1, 2)]]),
    }

    def reset(self):
        self.grid = [[0] * self.W for _ in range(self.H)]
        self.score = 0
        self.lines = 0
        self.over = False
        self._spawn()

    def _spawn(self):
        self.kind = random.choice(list(self.PIECES))
        self.rot = 0
        self.px, self.py = 3, 0
        if self._collides(self.px, self.py, self.rot):
            self.over = True

    def _blocks(self, px, py, rot):
        rots = self.PIECES[self.kind][1]
        for dx, dy in rots[rot % len(rots)]:
            yield px + dx, py + dy

    def _collides(self, px, py, rot):
        for x, y in self._blocks(px, py, rot):
            if x < 0 or x >= self.W or y >= self.H:
                return True
            if y >= 0 and self.grid[y][x]:
                return True
        return False

    def _lock(self):
        color = self.PIECES[self.kind][0]
        for x, y in self._blocks(self.px, self.py, self.rot):
            if 0 <= y < self.H:
                self.grid[y][x] = color
        full = [y for y in range(self.H) if all(self.grid[y])]
        if full:
            for y in full:
                del self.grid[y]
                self.grid.insert(0, [0] * self.W)
            self.lines += len(full)
            self.score += (0, 100, 300, 500, 800)[len(full)]
        self._spawn()

    def handle_key(self, key):
        if self.over:
            if key == "SPACE":
                self.reset()
            return
        if key in ("LEFT", "a") and not self._collides(self.px - 1, self.py, self.rot):
            self.px -= 1
        elif key in ("RIGHT", "d") and not self._collides(self.px + 1, self.py, self.rot):
            self.px += 1
        elif key in ("DOWN", "s"):
            if not self._collides(self.px, self.py + 1, self.rot):
                self.py += 1
        elif key in ("UP", "w"):
            nr = (self.rot + 1) % len(self.PIECES[self.kind][1])
            for kick in (0, -1, 1, -2, 2):
                if not self._collides(self.px + kick, self.py, nr):
                    self.px += kick
                    self.rot = nr
                    break
        elif key == "SPACE":
            while not self._collides(self.px, self.py + 1, self.rot):
                self.py += 1
            self._lock()

    def tick(self):
        if self.over:
            return
        if not self._collides(self.px, self.py + 1, self.rot):
            self.py += 1
        else:
            self._lock()

    def render(self):
        cells = [row[:] for row in self.grid]
        if not self.over:
            for x, y in self._blocks(self.px, self.py, self.rot):
                if 0 <= y < self.H and 0 <= x < self.W:
                    cells[y][x] = self.PIECES[self.kind][0]
        rows = ["╔" + "══" * self.W + "╗\n"]
        for y in range(self.H):
            row = ["║"]
            for x in range(self.W):
                v = cells[y][x]
                row.append(f"{fg(v)}██{RESET}" if v else " ·")
            row.append("║\n")
            rows.append("".join(row))
        rows.append("╚" + "══" * self.W + "╝\n")
        status = f"score: {self.score}   lines: {self.lines}"
        if self.over:
            status += f"   {fg(203)}game over — Space{RESET}"
        return "".join(rows) + status
